(function(){
  var d = (typeof result === 'string') ? JSON.parse(result) : result;
  if (d && d.data) {
    var su = d.data.streamURL || [];
    for (var i=0;i<su.length;i++){
      if (su[i].status === 1 && !su[i].onlyVIP && su[i].stream) return su[i].stream;
    }
    if (su.length) return su[0].stream;
  }
  return '';
})()

ruleToc.chapterList:
@js:
(function(){
  try{ book.type = 32; }catch(e){}
  var out = [];
  var j = null;
  try { j = (typeof result === 'string') ? JSON.parse(result) : result; } catch(e){}
  if (!j || !j.data) return out;
  var list = j.data.listSong || [];
  if (!list.length && j.data.items) list = j.data.items;
  if (!list.length && j.data.streamURL) {
    var sk = j.data.key || '';
    if (sk) {
      return [{
        name: (j.data.name || 'Track 1') + (j.data.artistName ? ' - ' + j.data.artistName : ''),
        url: 'https://graph.nct.vn/api/v1/song/detail/' + sk
      }];
    }
  }
  var seen = {};
  for (var i=0;i<list.length;i++){
    var it = list[i] || {};
    var k = it.key || '';
    if (!k || seen[k]) continue;
    seen[k] = 1;
    var nm = it.name || ('Track ' + (i+1));
    var ar = it.artistName || (it.artist && it.artist.length ? it.artist[0].name : '');
    var u = 'https://graph.nct.vn/api/v1/song/detail/' + k;
    out.push({
      name: (i+1) + '. ' + nm + (ar ? ' - ' + ar : ''),
      url: u
    });
  }
  return out;
})()
